import { randomUUID } from 'node:crypto'
import { appendFile, mkdir, readFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

const postsFile = join(process.cwd(), '.data', 'posts.jsonl')

export async function getPosts(): Promise<Post[]> {
  let contents: string

  try {
    contents = await readFile(postsFile, 'utf8')
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []
    throw error
  }

  return contents
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line) as Post)
    .reverse()
}

export async function addPost(title: string, content: string): Promise<Post> {
  const post: Post = {
    id: randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  await mkdir(dirname(postsFile), { recursive: true })
  await appendFile(postsFile, `${JSON.stringify(post)}\n`, 'utf8')

  return post
}

